import React, { useState } from 'react';
import LoginScreen from './components/auth/LoginScreen/LoginScreen';
import AppLayout from './components/layout/AppLayout/AppLayout';
import Admin5Dashboard from './pages/admin5/Admin5Dashboard/Admin5Dashboard';

// Importe as novas páginas
import CreateAdminPage from './pages/admin5/CreateAdminPage/CreateAdminPage';
import ListAdminsPage from './pages/admin5/ListAdminsPage/ListAdminsPage';
import CreateOngPage from './pages/admin5/CreateOngPage/CreateOngPage';
import ListOngsPage from './pages/admin5/ListOngsPage/ListOngsPage';
import ListUsersPage from './pages/admin5/ListUsersPage/ListUsersPage';
import ReportsPage from './pages/admin5/ReportsPage/ReportsPage';
import CreatePrizePage from './pages/admin5/CreatePrizePage/CreatePrizePage';
import ListPrizesPage from './pages/admin5/ListPrizesPage/ListPrizesPage';

function App() {
  const [userRole, setUserRole] = useState(null);
  const [currentPage, setCurrentPage] = useState('dashboard');

  const loginAs = (role) => {
    setUserRole(role);
    setCurrentPage('dashboard');
  };

  const logout = () => {
    setUserRole(null);
  };

  const navigate = (page) => {
    setCurrentPage(page);
  };

  // Atualiza o roteador para incluir as novas páginas
  const renderPage = () => {
    if (userRole !== 'admin5') {
        return <h1>Painel para {userRole}</h1>;
    }

    switch (currentPage) {
      case 'dashboard':
        return <Admin5Dashboard onNavigate={navigate} />;
      case 'create_admin':
        return <CreateAdminPage />;
      case 'list_admins':
        return <ListAdminsPage />;
      case 'create_ong':
        return <CreateOngPage />;
      case 'list_ongs':
        return <ListOngsPage />;
      case 'list_users':
        return <ListUsersPage />;
      case 'reports':
        return <ReportsPage />;
      case 'create_prize':
        return <CreatePrizePage />;
      case 'list_prizes':
        return <ListPrizesPage />;
      default:
        return <h1>Página: {currentPage}</h1>;
    }
  };

  if (!userRole) {
    return <LoginScreen loginAs={loginAs} />;
  }

  return (
    <AppLayout onNavigate={navigate} onLogout={logout} activePage={currentPage}>
      {renderPage()}
    </AppLayout>
  );
}

export default App;
